script:
situation_event = {
	id = grand_archive.8620
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		owner = {
			is_nomadic = yes
			count_owned_nonprimary_starbase = {
				count < value:systems_available_for_sabotage
				limit = {
					is_waystation_starbase = yes
					solar_system = { has_star_flag = available_for_sabotage }
				}
			}
		}
	}

	immediate = {
		owner = {
			if = {
				limit = { is_difficulty = 6 }
				every_owned_nonprimary_starbase = {
					limit = {
						is_waystation_starbase = yes
						solar_system = { NOT = { has_star_flag = available_for_sabotage } }
					}
					solar_system = { set_star_flag = available_for_sabotage }
				}
			}
			else = {
				export_trigger_value_to_variable = {
					trigger = is_difficulty
					variable = difficulty_value
				}
				while = {
					count = difficulty_value
					random_owned_nonprimary_starbase = {
						limit = {
							is_waystation_starbase = yes
							solar_system = { NOT = { has_star_flag = available_for_sabotage } }
						}
						weights = {
							base = 1
							modifier = {
								add = 2
								has_starbase_size = starbase_waystation_2
							}
							modifier = {
								add = 4
								has_starbase_size = starbase_waystation_3
							}
							modifier = {
								add = 5
								solar_system = {
									any_fleet_in_system = { is_arkship_fleet = yes }
								}
							}
						}
						solar_system = { set_star_flag = available_for_sabotage }
					}
				}
			}
		}
	}
}

